using System;
using System.Collections.Generic;
using UnityEngine;

namespace Metro.View {
    /// <summary>
    /// Serialized formation prefab table: one promoted consist per editor formation
    /// key, plus the promoted livery variants. Generated by the Editor's train
    /// catalogue builder from the promoted prefab folder.
    /// </summary>
    [CreateAssetMenu(menuName = "Metro/Train Catalogue", fileName = "TrainCatalogue")]
    public sealed class TrainCatalogue : ScriptableObject {
        public const string AssetPath = "Assets/StationDesigner/Generated/TrainCatalogue.asset";

        [Serializable]
        public sealed class Entry {
            public string key = "";
            public string stock = "";
            public int cars;
            public string power = "";
            public GameObject prefab;
            public string prefabPath = "";
            public string resourcePath = "";
            /// <summary>Model scale baked into the promoted prefab (1 when none).</summary>
            public float bakedScale = 1;
        }

        public int schemaVersion = 1;
        public Entry[] entries = Array.Empty<Entry>();

        Dictionary<string, Entry> index;

        public void EnsureIndex() {
            if (index != null && index.Count == (entries?.Length ?? 0)) return;
            index = new Dictionary<string, Entry>(StringComparer.Ordinal);
            foreach (var entry in entries ?? Array.Empty<Entry>()) {
                if (entry == null || string.IsNullOrEmpty(entry.key)) continue;
                index[entry.key] = entry;
            }
        }

        public bool Has(string key) { EnsureIndex(); return !string.IsNullOrEmpty(key) && index.ContainsKey(key); }

        public bool TryGet(string key, out Entry entry) {
            entry = null;
            EnsureIndex();
            if (string.IsNullOrEmpty(key) || !index.TryGetValue(key, out entry)) return false;
            if (!entry.prefab && !string.IsNullOrEmpty(entry.resourcePath))
                entry.prefab = Resources.Load<GameObject>(entry.resourcePath);
            return true;
        }

        public GameObject Prefab(string key) => TryGet(key, out var entry) ? entry.prefab : null;

        public IEnumerable<Entry> Entries => entries ?? Array.Empty<Entry>();

        void OnEnable() => index = null;
    }
}
